// 時間複雜度: O(min(m, n))，空間複雜度: O(1)
function uniquePaths(m, n) {
    let result = 1;
    const k = Math.min(m, n) - 1;
    for (let i = 1; i <= k; i++) {
        result = result * (m + n - 1 - i) / i; // 每一步都整除，結果保持整數
    }
    return Math.round(result);
}

