#include <vector>
using namespace std;

class Solution {
public:
    /**
     * 方法一：二維動態規劃
     * 時間複雜度: O(m * n)
     * 空間複雜度: O(m * n)
     */
    int uniquePaths(int m, int n) {
        vector<vector<int>> dp(m, vector<int>(n, 1));

        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = dp[i-1][j] + dp[i][j-1];
            }
        }

        return dp[m-1][n-1];
    }

    /**
     * 方法二：一維動態規劃（推薦）
     * 時間複雜度: O(m * n)
     * 空間複雜度: O(n)
     */
    int uniquePaths_1d(int m, int n) {
        vector<int> dp(n, 1);

        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[j] += dp[j-1];
            }
        }

        return dp[n-1];
    }

    /**
     * 方法三：數學公式
     * 時間複雜度: O(m + n)
     * 空間複雜度: O(1)
     */
    int uniquePaths_math(int m, int n) {
        long long result = 1;
        int total_steps = m + n - 2;
        int down_steps = m - 1;

        // 選較小的數計算
        if (down_steps > total_steps - down_steps) {
            down_steps = total_steps - down_steps;
        }

        // 逐步計算組合數
        for (int i = 0; i < down_steps; i++) {
            result = result * (total_steps - i) / (i + 1);
        }

        return (int)result;
    }
};

