class Solution {
    /**
     * 方法一：二維動態規劃
     * 時間複雜度: O(m * n)
     * 空間複雜度: O(m * n)
     */
    public int uniquePaths(int m, int n) {
        int[][] dp = new int[m][n];

        // 初始化
        for (int i = 0; i < m; i++) {
            dp[i][0] = 1;
        }
        for (int j = 0; j < n; j++) {
            dp[0][j] = 1;
        }

        // 填充
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = dp[i-1][j] + dp[i][j-1];
            }
        }

        return dp[m-1][n-1];
    }

    /**
     * 方法二：一維動態規劃（推薦）
     * 時間複雜度: O(m * n)
     * 空間複雜度: O(n)
     */
    public int uniquePaths_1d(int m, int n) {
        int[] dp = new int[n];

        // 初始化
        for (int j = 0; j < n; j++) {
            dp[j] = 1;
        }

        // 逐行更新
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[j] += dp[j-1];
            }
        }

        return dp[n-1];
    }

    /**
     * 方法三：數學公式
     * 時間複雜度: O(m + n)
     * 空間複雜度: O(1)
     */
    public int uniquePaths_math(int m, int n) {
        long result = 1;
        int totalSteps = m + n - 2;
        int downSteps = m - 1;

        // 選較小的數計算
        if (downSteps > totalSteps - downSteps) {
            downSteps = totalSteps - downSteps;
        }

        // 逐步計算組合數
        for (int i = 0; i < downSteps; i++) {
            result = result * (totalSteps - i) / (i + 1);
        }

        return (int)result;
    }
}

