// 組合數學：共走 m+n-2 步，選其中 m-1 步往下 → C(m+n-2, m-1)
// 用 long long 逐步計算，每一步都能整除
// 時間複雜度: O(min(m, n))，空間複雜度: O(1)
int uniquePaths(int m, int n) {
    long long result = 1;
    int k = (m < n ? m : n) - 1;
    for (int i = 1; i <= k; i++) {
        result = result * (m + n - 1 - i) / i;
    }
    return (int)result;
}
